// Package machinequint writes a table std::machine reads out of a transition
// function as a Quint module. The module holds the machine and nothing about what
// it should do: properties live in a hand written module that imports it, so a
// regenerated file cannot drop one.
package machinequint

import (
	"fmt"
	"strings"

	"github.com/kizu-lang/kizu/internal/machinelean"
)

// Render writes the module `name` for a table of every pair.
func Render(name string, table machinelean.Table) (string, error) {
	if err := table.Validate(); err != nil {
		return "", err
	}
	out := strings.Builder{}
	out.WriteString("// GENERATED by scripts/machine-quint. Do not edit.\n")
	fmt.Fprintf(&out, "module %s {\n", name)
	writeSum(&out, "State", table.States)
	writeSum(&out, "Event", table.Events)
	writeSum(&out, "Outcome", table.Outcomes)
	out.WriteString("\n")
	writeSet(&out, "events", "Event", table.Events)
	writeSet(&out, "outcomes", "Outcome", table.Outcomes)
	writeSet(&out, "ends", "State", table.Ends)
	out.WriteString("\n")
	out.WriteString("  pure val moves: (State, Event) -> (State, Outcome) = Map(\n")
	for _, move := range table.Moves {
		fmt.Fprintf(&out, "    (%s, %s) -> (%s, %s),\n", move.From, move.Event, move.To, move.Outcome)
	}
	out.WriteString("  )\n\n")
	out.WriteString(`  var state: State
  var previous: State
  var event: Event
  var outcome: Outcome
  var moved: bool

`)
	out.WriteString("  action init = all {\n")
	fmt.Fprintf(&out, "    state' = %s,\n    previous' = %s,\n", table.Start, table.Start)
	out.WriteString("    nondet e = oneOf(events) event' = e,\n")
	out.WriteString("    nondet o = oneOf(outcomes) outcome' = o,\n    moved' = false,\n  }\n\n")
	writeStep(&out)
	return out.String(), nil
}

// writeStep writes the moves of a run. A random event at each step would mostly
// be a refusal, and a run would end long before the late states, so half the steps
// choose among the events that do not lead to an end. A search that finds nothing
// over runs that never got there would say nothing.
func writeStep(out *strings.Builder) {
	out.WriteString(`  action take(e: Event): bool = {
    val answer = moves.get((state, e))
    all {
      state' = answer._1,
      previous' = state,
      event' = e,
      outcome' = answer._2,
      moved' = true,
    }
  }

  action anyEvent = {
    nondet e = oneOf(events)
    take(e)
  }

  action onward = {
    val open = events.filter(e => not(ends.contains(moves.get((state, e))._1)))
    all {
      open != Set(),
      nondet e = oneOf(open)
      take(e),
    }
  }

  action step = any { anyEvent, onward }
}
`)
}

// writeSet writes one list of names as a Quint set.
func writeSet(out *strings.Builder, name, element string, values []string) {
	fmt.Fprintf(out, "  pure val %s: Set[%s] = Set(%s)\n", name, element, strings.Join(values, ", "))
}

// writeSum writes one enum as a Quint sum type.
func writeSum(out *strings.Builder, name string, variants []string) {
	fmt.Fprintf(out, "  type %s = %s\n", name, strings.Join(variants, " | "))
}
